def _coerce(value, default):
    """Coerce `value` (typically a string from the environment) to the type
    of `default` (bool, int, float, or str)."""
    # bool must be checked before int because bool is a subclass of int.
    if isinstance(default, bool):
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            return value.strip().lower() in ("1", "true", "yes", "on")
        return bool(value)
    if isinstance(default, int):
        return int(value)
    if isinstance(default, float):
        return float(value)
    return str(value)


def load_config(defaults: dict, env: dict) -> dict:
    """Return a copy of `defaults` where any env var APP_<KEY> overrides the
    value for key <key> (lowercased), coerced to the type of the default."""
    cfg = dict(defaults)
    for name, value in env.items():
        if not name.startswith("APP_"):
            continue
        key = name[len("APP_"):].lower()
        if key in cfg:
            cfg[key] = _coerce(value, cfg[key])
    return cfg
